𗴮𘊳/03.content:
{{header
 | title    = {{Tangut|[[𗴮𘊳]]}} (''The Forest of Categories'')
 | author   = 
 | section  = {{Tangut|𗴮𘊳𘕕𗡪𗱋}} (Volume III)
 | previous = {{Tangut|[[𗴮𘊳/02|𗴮𘊳𗍫𗡪𗱋]]}}
 | next     = {{Tangut|[[𗴮𘊳/04|𗴮𘊳𗥃𗡪𗱋]]}}
 | notes    = Carvers: {{Tangut|𗜫𘄱, 𗍼𗉔, 𗜓𘏞, 𘋇𗸤, 𘀄𗲾, 𘀄𗸹, 𗒅𗷌𗥝, 𘏞𗬐, 𗣆𗘆}}
}}

{{Tangut|《𗴮𘊳𘕕𗡪𗱋》}}

{{Tangut|《𘞌𘓟》𘄿𗰗}}

{{Tangut|𗔬𗩇𗺹、𘅰𗒯、𘅧𗲁、𗪨𘕘、𘃣𗻼、𗦆𗩇𘓖、𘝻𗎉、𗏆𗷅}}

{{Tangut|𗔬𗩇𗺹𗼻𗹬𗑠𗌹𗭍𗥩𘙇𘃡。𗭒𗓓𗗟𘅍，𗼮𘜶𗱢𗆐。𗅉𗀚𘓐𘆄𗋚𗗎：「𘅇𗶷𘉞」𘘣。𗩇𗺹𘒣：「𘓐𗑠𗥩𗷳𘙇𘃡，𘓟𘇄𘏚𗰓𗁁？」𘘣，𗼮𗃡𘐏𗳒𘙇𗶹。𗤁𗂧𗤀𘓐𘟂。}}

{{Tangut|𘅰𗒯𗑟𘎆𗑠𗠇𗠰𗥩𘃡。𗑟𗷝𗆐，𘌽𗏣𘅰𗒯𗠇𗅋𗠰。𗏡𗾞𗑟𗆐，𗋸𗅉𗦬𗋚𗠰。𗤁𗂧𗤀𘓐𘟂。}}

{{Tangut|𘅧𗲁𗉘𘝨，𘝵𗂧𗹦𗼓𗫻𘏚𘋩𘙇𘞓。𗈇𗏣𘙌𗦎，𗍏𗑪𗑠𗈪𘄏。𗍏𗑪𘅧𗲁𗗙𘏨𘟫𗀓𗧠，𗟲𗱁𘖑𘜕。𘅧𗲁𗥤𗤶𗖵，𗈪𗥠𘃡，𗞞𗨛。𗆮𗅉，𗍏𗑪𗞞𗢏。𘅧𗲁𗉮𘃛𘏨𘟫𗞞𗱌，𗢤𗥦𘕿𘂬𘃡。𘌽𘅣《𗢆𘃟𘝞》𘂤𘎪。}}

{{Tangut|𗪨𘕘，𗅉𗦻𗐪𘘣，𘄴𗂧𘓐𘟂。𘝵𗎭𘃂𗏣𗫌𘎆𗱀𗐱𗗾𘙣，𗪨𘕘𗴺𗗙𗞞𗤄：「𗗾𘙣𗫶𗫂𗰓𗋂？」𘘣。𗴺𘗮𗷍𗳒𘒣𘘣：「𘀍𗋚𗠈𘉞」𘘣。𘎪𘃪𗅉，𗴺𗳜𘒣：「𗟲𘙌𗷁𗧓」𘘣，𗉮𘃛𗁮𗗣，𗪨𘕘𗗙𗞞𗠩，𘓟𗅋𘇄𗗙𗏴𗑩𘔼𘃞。𗤁𗂧𗤀𘓐𘟂。}}

{{Tangut|𘃣𗻼𗡸𘓐𗖌𗑠𗋻𗯴𘙌𗥩。𘙇𗭻，𗷝𗆐。𗋽𘜶𗛧𗦎，𘃣𗻼𗉮𘃛𗋻𗞁𘙌𗃋，𗞞𗢏。𘌽𗫂𘓟𘓁𘟂𗫶，𗾖𘈷𘌽𘝦𗅋𗭍𘃞。}}

{{Tangut|𗦆𗩇𘓖，𗅉[𗦻]<ref>The character {{Tangut|𗦻}} is missing in the original text, and is here supplied by analogy with the frequent occurrence of the word {{Tangut|𗅉𗦻}} in similar contexts elsewhere in the text.</ref>𗕸𗄋𘘣，𘄊𘎫𗴒𗑠𗈪𗄛𘝨，𗳷𗂧𗥦𘙌𗨳。𗳷𘟙𘔯𗨙，𘒣𘘣：「𘀍𗂧𗆮𘅍，𘕣𗳒𘓊𗸦𗗙𗖄𘆏𘉞？」𘘣。𗕸𗄋𘒣：「𘋨𗗙𗿣𗪺𗳒𗰜𗂧𗆮𘜘，𗌭𗓱𘋨𗂧𘒏𗄈𘘮𗂧，𘒏𗑠𗸓𘅍，𘘮𘒏𘋨𘒏𗗙𗢭𗰗𗼲𗈱𗰣𗳜𘈔𗣬𗧓」𘘣。𗏡𗕸𗄋𗰜𗂧𘙌𗆮。𘋨𘛃𗋚𗒐𗳷𗂧𗇏𗤭𘕘𗘼𘒏𗄈，𗐾𗂧𗀔𗕼𗶹。𗐾𘟙𗦆𘟙𘋩𗅮𘒏𗌽𘑨𗀓。𗩇𘓖𘟙𘒏𗄈，𗐾𗗙𗥞𗶹。𗪘𗳷𗂧𗖄𘆏，𘓟𗅋𘇄𗑩𘔼，𗳷𘒏𗑠𗸓𗿳，𘝵𘒏𗢭𗰗𗼲𗰣𗋚𗳜𗞞𘈔𘃡，𘂆𗅋𘘪。𗳷𘒏𗆭𗓰𘃡，𗌭𗩇𘓖𘝵𘒏𘆏𗈪𗔼，𗉮𘃛𗳷𘒏𘜶𘒚。𗳷𘟙𗓁𗅉𘜶𗕣，𘕘𗘼𗗙𗖣，𘝵𘝵𗞞𗜍。𗉔𗚂𘟙𗤀𘓐𘟂。}}

{{Tangut|𘝻𗎉，𗅉𗦻𗩿𗺹𘘣，𗽮𗭴𗼻𘍞𘓐𘟂。𗑌𘏸𗤒𗅁，𗄱𗉔𘛔𗅂𗿒𘙇𘃡。𗞝𗣈𘝵𗼻𘍞𗅁𘕂𗶹。𗜫𗰂𗎘𘕿𗫡，𗰗𗰣𘁛𘞁𗔔𘆝𗍰𗳒𗐤𗆐。𗉮𘃛𗞞𗤄：「𘕣𗾞𗆮𘉞？」𘘣。𘝻𗎉，𗭒𗓓𗆮𗡶𗹳𗜈𗇋𗗙𘒩𗠪，𗾞𘜍𘁛𘞁𘜔𗗙𘄇𗟻。𘝻𗎉，𗼻𘍞𗅁𗭊𘕂，𘙌𗆮𗪘𗥩𗾞𘙇𘃡，𗿳𗷝𗫡𗖵，𗍁𘗠𗅁𗅋𗶷，𗬫𗅉𗫻。𗹳𗜈，𘝻𗎉𗗙𗞞𗤄，𗊬：「𘘮𘁛𘞁𘆄𗑠𗥩𗷳𘙇𘃡，𘗬𘗪𘏚𗤋」𘘣。𗏡𗾞，𘁛𘞁𘜔𗄊𗔔𘆝𗍰𗳒𘔯𗆐𗉘，𗋸𗅉𗍁𗅁𘙇𗶹。𘌽𘅣《𘟑𗤀𘝞》𘂤𘎪。}}

{{Tangut|𗏆𗷅，𗅉𗦻𗿄𗫲𘘣，𗄽𗭴𗷭𗐐𗼻𘍞𘓐𘟂。𘋻𗽮𗼻𘍞𘑲𘃟𘌜𗑠𗑟𘎆𘙇𘃡。𗸴𘊡，𘟙𗍁𗅁𗋚𘝪𗈜，𘌞𘚔𘙌𗥩。𘃟𘌜𘒣：「𗢭𗼑𗰭𗏁𗾞，𗡗𘙣𗼦𘌐𗔄𘃡𗿳𘅍𗭻𘉞」𘘣，𗞞𗨛。𗏡𘃟𘌜𗴺𘋩𘒣𗓁，「『𗡞𗼲𗶷𗷳𗀔𗄼𗧓』𘘣𗫂，𘀍𘓟𘉞𗗂？」𘘣。𘃟𘌜𘒣：「𗿄𗫲𗫂𘓟𗿷𘓐𘟂，𗷳𘇄𗇋𗅔」𘘣，𘎪𘃪𘅍，𗉮𘃛𗿄𗫲𗫡𗆐。𗍫𘓐𗳳𗀚𗴺𘋩𗦞，𗶹𘄽𘄽𗞞𘚻𘅎。𗏡𘟑𗤀𘓐𘟂。}}

{{Tangut|《𘋼𗹐》𘄿𗰗𘈩}}

{{Tangut|𗳷𗫔、𗩇𗴀、𘏸𘊐、𗉔𘏉、𘄀𗫔、𗌃𗘬、𘑲𗁀、𗕌𗢱、𗫐𘈫、𗷲𗿖}}

{{Tangut|𗳷𗫔𗔬𘍑𘓖𗗙𗪺𗇋𘟂𗅉𗂸𘕹𗟙𘈘𘈘 𗹐𗳒𘍑𘓖𗗙𗗎𘍑𘓖𗦁𗄈𗧶𗧶𗳷𗫔𘒫 𘕹𗟙𗗙𗫌𘋩𗲻𗜍𗶷𗟻𘕹𗟙𘛺𘛦𗈪𗢵 𗐯𗶷𗗟𘅍𗵫𗷝𗬀𗌭𗓈𘎼𗱢𗒾𗳷𗫔𘕹 𗟙𗗙𗑗𗹐𘒣𗋚𗾫𗜍𘖑𘜕𗅉𘂆𘍑𘓖𗗙 𘒣𘇄𘏚𗤋𘔼𘝵𗥦𗸇𗙼𘙌𗸋𗞞𗢏𘌽𘅣 𗰹𗊧𘝞𘂤𘎪}}

{{Tangut|𗩇𗴀𗅉𗦻𘜸𗐐𘘣𗕔𗤩𗼻𘍞𘓐𘟂𗙍𗄵 𘒏𗩈𘙇𘃡𘟑𗂧𘒏𗗙𘴈𘒚𗟻𗩈𗌮𗯹𘃡 𗜍𗗟𘅍𗠉𗐉𘘃𗳒𘒣𘘣𘴈𗾖𗪐𗫂𗈶𘅍 𗠉𗐉𗅋𘕠𘃡𘘣𗉮𘃛𗠉𗐉𘘃𗳒𗞞𗢏𘌽 𘅣𘟑𘝞𘂤𘎪}}

{{Tangut|𘏸𘊐𗔬𗩇𗺹𘟙𗤀𘓐𘟂𗍠𗂋𗹠𗩇𗺹𘟠 𗖵𗈪𗢵𗤔𘃡𘏸𘊐𗕣𗍠𗳒𗩇𗺹𗗙𘙌𘄩 𗩇𗺹𗈪𗕣𘓐𘒫𘏸𘊐𗗙𗯹𗟻𘏸𘊐𗖸𘒣 𗈪𗣃𗰣𘎪𘘦𘗐𗈶𗧓𘘣𗩇𗺹𘒣𘕣𘀽𘉞 𘘣𘏸𘊐𘒣𗂸𘀲𘏼𘋨𘙌𘄩𗧓𗭪𘖑𗫶𘝗 𗢄𘋨𗗙𘙌𘄩𗧓𗅔𘘣𗩇𗺹𘒣𘄩𗸦𘕿𘕋 𘂬𘘣𗉮𘃛𗍠𗃵𗙼𘏩𗗎𗅲𘙇𘃡𗤁𗂧𗤀 𘓐𘟂}}

{{Tangut|𗉔𘏉𗏲𗂧𘓐𘟂𘟑𗣛𗥣𗤀𗘼𘏸𗕔𗥑𘃡 𗣛𗥣𗏹𗪯𗦉𘄴𘞽𗑠𗧶𗧶𗰘𘂤𗉔𘏉𘖉 𘅣𘟣𘔼𗣛𗥣𗫻𘋩𘙇𗆐𘖉𘃪𗣈𗗟𘅍𗣛 𗥣𗺌𗺏𗅋𗔌𗳒𗉔𘏉𗗙𗌽𗯹𗒕𗀔𗶠𘃡 𘒣𘘣𗧓𘋨𘃡𘝶𗦜𘘣𗉔𘏉𘒣𘓺𘋨𘀲𘏼 𘋨𗍊𘉞𘃞𘘣𘋨𗞞𘋞𘝵𗳜𘌽𘅣𗪘𘟑𗤀 𘝞𘂤𘎪}}

{{Tangut|𘄀𗫔𗅉𗦻𘕘𗰔𘘣𗥡𗂧𘓐𘟂𘕘𗰔𘋨𘋩 𘒣𘘣𗂸𗗙𗿢𘟫𗌽𘎾𘗯𗂸𘓐𗖌𗗙𗜍𗶷 𗧓𘘣𘋨𘒣𗖶𘟂𘘣𘕘𗰔𘒣𘑲𗘼𘟂𘘣𘋨 𘄽𘄽𗕣𗳒𘒣𘘣𘘚𗸱𗳭𗧠𗫂𗈶𘕋𘟂𘅇 𘐉𘉞𘘣𗉮𘃛𘈑𗸆𘙌𘒫𗃵𗙼𗝿𗟻𗜍𗗟 𘅍𘄀𗫔𘖑𗳢𗃵𗙼𗝠𗺞𘙌𗜈𗈪𗷷𗋕𗿳 𘴈𗂸𗸹𗫲𗒯𗗎𘒣𘓺𘋨𘘖𗋚𗫩𘉞𘄀𗫔 𗗙𘒣𗫂𗹐𘃞𘓺𘋨𗋚𗡣𘘣𘋨𗉣𗋚𗳜𗉮 𘃛𗞞𘐉𗂈𗼛𘓐𗃵𗇫𗆐𘋨𘒣𘅇𗇫𗐱𘘣 𗂸𗗙𗹐𗏴𗭪𘗐𗨻𘘣𘟑𘈫𘋨𗤀𘓐𘟂𘌽 𘅣𘟑𗤀𘝞𘂤𘎪}}

{{Tangut|𗌃𗘬𗅉𗦻𗔗𗦮𘘣𘔜𘛫𗼻𘍞𘓐𘟂𗁀𘈫 𗤀𗓽𗭴𗼻𘍞𗅁𗾩𘍑𘃡𘝨𘋨𘊶𘓺𘁤𗩍 𗷬𘝦𘃡𗾞𗇸𘓐𗖌𗞞𗜍𗖵𘓺𘁤𗫌𘋩𘙌 𘄔𗌃𗘬𗓁𗅉𗂈𗼛𘓐𘒫𗓽𗭴𘚔𘕿𘙌𗭻 𗟻𗉮𘃛𘓺𘁤𗷬𗗙𗋚𗣈𘆽𗙼𗀚𗌃𗘬𗷬 𗗙𘗒𘆝𗀔𗱢𗱅𗟻𘕣𘔼𘓐𗜍𘉞𘘣𘓺𘁤 𘴈𗕣𘋨𘋩𘙌𗅮𘋨𗌃𗘬𗗙𗜍𗧠𗌃𗘬𘒣 𗂸𘒣𗈪𗣃𘙇𘎪𗟻𗧓𘅍𗈶𘗐𗛮𗧓𘘣𘋨 𘒣𘕣𘀽𘉞𘘣𗊬𘓺𘋨𗷬𗔱𗥁𗟻𗳒𘓐𘄽 𗗙𗜍𗫂𗂧𘝶𗦜𘇚𘃡𗂸𘝵𘝵𗜍𗧠𘘣𗉮 𘃛𗥦𗃵𗙼𗸋𗊴𗛧𘅞𘏋𘋨𘒇𗇋𘗠𗘩𗀹 𗷆𗌃𗘬𘋩𗹓𘃡𘓺𘁤𘋩𘕋𘙌𘖗𗶷𘉞𘘣 𗌃𗘬𗅋𗨉𘋨𘓐𘒫𗃎𗳒𘅋𗅌𗦞𗟻𗱢𗑯 𗅋𗢵𘓺𘁤𗌃𗘬𗅋𗦞𘟀𗅉𘘦𘋨𗗙𗖸𘀍 𘛟𗋗𘔫𗇈𗔛𘝨𘂆𗈶𘕋𘄩𗇋𘓐𗱠𗎭𗅁 𗱚𗅂𗅁𘗒𗇋𘗠𗎘𘙌𗶚𘖑𘜕𗫈𗍳𗹦𗼓 𘙇𘃡𘝶𗦜𘌽𘓐𘞪𗗙𘛥𗌻𘖑𗩱𘘣𘋨𘒣 𗹦𗼓𘛢𘓐𗑠𘙰𘘣𗉮𘃛𗌃𗘬𗗙𗎫𗃎𗂸 𗦻𗈪𗱁𘃡𗞞𘕖𘕕𗰗𗕑𘘘𘔭𗞞𘓯𘌽𘅣 𗏡𘟑𗤀𘝞𘂤𘎪}}

{{Tangut|𘑲𗁀𗅉𗦻𗩇𘎫𘘣𘈫𗭴𗼻𘍞𘓐𘟂𘟑𗙔 𘋨𗤀𗪦𘜳𘏸𘙌𘒫𗋕𗖵𗼻𘍞𗅁𗱕𗅂𗧥 𘄎𘝣𗈹𗦾𘃡𗆎𘜳𘏸𗭒𗈪𗓓𘑲𗁀𘞪𗅋 𗶷𗟔𘚢𘆄𗾄𗓽𗭴𗣔𗇊𗼻𘍞𗅁𗱢𘐆𘒣 𘘣𗛘𘘇𗫻𗯩𗗱𗗶𗗙𗤄𗦇𘕣𘂬𘘣𘋨𘒣 𗖶𘟂𘘣𘑲𗁀𘒣𘴈𘒏𗩈𗃛𘎫𘟂𘘣𗋕𗾞 𘋨𘝦𘃡𗃛𘎫𗗙𗞞𗜍𗟻𗅉𗋕𗿳𗁀𘍑𗼻 𘍞𗅁𘝚𗇋𘑲𗿖𘝦𘃡𗍁𗦳𗞞𗜍𗓷𗼻𘍞 𘝵𗜈𗵐𘊄𘙌𗦳𗏡𘑲𗿖𘆄𗍁𘗠𘏒𗣈𘑲 𗁀𗗙𘔯𗨙𗥦𘙌𗨳𘑲𗁀𗪘𗞞𘛒𘝪𗈜𗇋 𘓐𘜔𗄊𗰖𗄭𗟻𘝵𗌮𗋕𘆄𗗙𗫻𘏚𗤫𗹨 𘙇𗋚𘃡𘝵𗯩𘗲𗴴𘜘𗟻𗴮𘇂𗗔𗣼𗭍𗟻 𗙔𘋨𘈃𘍳𘆒𗄾𗰗𗕑𘘘𘔭𗞞𘓯𗏡𘟑𗤀 𘓐𘟂𘌽𘅣𗬐𘓣𗭺𗍏𘟑𗤀𘝞𘂤𘎪}}

{{Tangut|𗕌𗢱𗔬𗂧𘓐𘟂𗩇𗺹𗫂𗂸𗗙𗤄𘒣𘓊𗸦 𗫂𘕣𗍊𘋨𘟂𘘣𗫔𗂸𘒣𗸯𘋨𘟂𘉞𘘣𘂤 𗕌𗢱𘒣𗅋𗸯𘋨𘉞𘘣𘋨𘒣𘝶𗦜𗄻𘉞𘘣 𗕌𗢱𘖉𘒣𘀍𘑲𗄽𗼻𘍞𗵗𘉞𘝨𗤾𗣫𗗙 𗦳𗟻𗟭𘂤𘈷𗗙𘙌𗦳𗠔𘉞𘔼𘘦𗖵𗅋𗸯 𘟂𗄻𗧓𘘣𗩇𗺹𘴈𗕣𗋚𘎼𘙇𘈗𘃡𗟻𗫸 𗅉𗶩𘙾𗗙𗞞𗤄𗶩𘙾𘒣𗸯𘋨𘟂𘉞𘘣𘋨 𘒣𘝶𗦜𘘣𗊬𘒣𗂸𗓁𘋨𘄡𗌭𗂸𗹐𘘣𗕌 𗢱𗹐𘒣𘎪𘕿𗦢𗌭𗋕𗖵𘓺𘋨𗗙𗾈𘄡𘟂 𘉞𗳬𗧓𘘣𗩇𗺹𘴈𘚻𗫸𗕌𗢱𗗙𗈪𗁦𘴈 𘎮𗍷𘃡𗟻𗤁𗂧𗤀𘓐𘟂}}

{{Tangut|𗫐𘈫𗅉𗦻𘕘𗫲𘘣𗽕𘍑𗼻𘍞𘓐𘟂𘟑𘈫 𘋨𗤀𗏴𘜼𗜈𗟻𗈇𗏣𗧢𗪌𘂤𘙇𘐉𗜓𗘼 𗼻𘍞𗫡𘉑𘝦𘃡𗫐𘈫𗗙𗰻𗳒𘙌𗦞𘉞𘘣 𘖑𗳢𗧢𗪌𘟞𗜈𗒕𗀔𘐏𘃡𗫐𘈫𘟑𗂧𘙌 𘒫𘉢𘉢𗂸𘟂𘝶𗦜𗂧𗣫𘝦𘃡𘀇𗷼𗧓𘘣 𗉮𘃛𘟫𘖗𘝵𗘳𗧢𗪌𘄽𘄽𘙌𘓒𗟜𗳒𘓐 𘗒𗇐𗟻𗫐𘈫𗞞𗆇𗧢𗪌𗫐𘈫𗗙𗃒𗓰𗅁 𗱢𗝩𗟻𗠇𗈪𗧤𘃡𗎆𘴈𗱢𗆐𗑠𗱢𗔫𘋳 𗦇𗅁𗎆𗒵𘃡𗳒𗍌𗒹𘜍𘙌𗦎𗅋𗈶𗧢𗪌 𗐱𗂸𘃡𗟻𗧠𗫐𘈫𗞞𘕖𗈇𗗚𗯩𗂽𘓉𗟻 𗫐𘈫𗏴𘜼𗜈𗳒𗂽𘓉𗠫𘅍𗂽𗁮𗡅𗠵𗿳 𗂽𗌙𗠰𘈫𘋨𗞞𘒻𗙵𘋨𘙌𗂷𗧢𗪌𗑠𗶚 𘚕𗞞𗨻𗖊𘒫𗫐𘈫𗗙𗟨𗶷𗟻𗧢𗪌𘗯𘒣 𗫐𘈫𗞞𗏋𘘣𘓟𗗟𘂤𗫐𘈫𗤼𗯴𘟑𘒫𗖊𘝾𗙃𘋩𘙇𗶹𗫐𘈫𗖊𗗙𘒣𘘣𘟑𗙵𘋨𗜂 𘊳𘂤𘕂𗶹𗈱𗳒𗿝𗁷𗱢𗒯𗿝𗭒𘕿𗫐𘈫 𗗙𗥌𘝞𗞞𘂬𗈪𘜘𘕿𗫐𘈫𗧢𗪌𘂤𗈇𗗚 𗯩𗂽𘓉𗫻𗧓𘘣𗭪𘝶𗦜𗤋𘃞𘙇𘀽𘉞𘘣 𗖊𗋕𘒣𗖵𗧢𗪌𘋩𘙇𘎪𗀔𗞞𗛮𗫐𘈫 𘞌𗣜𗫻𘘣𗋚𘆏𘃡𘟑𗂧𗫡𗆐𗪘𗜈𗏴𘜼 𗞞𗈤𗭪𗙵𘋨𗗙𘐌𘃡𗋕𗗙𘈃𘍳𘆒𗋚𗄾 𗫐𘈫𗗙𗈪𗁦𗊄𘋺𘝻𘃡𗟻𗫐𘈫𗧢𗪌𘂤 𗰗𗢭𗤒𗭊𗫻𗪘𘙇𗶹𘝨𗫏𘜀𗫸𗆮𗿳𗴵 𗐄𗸕𗴂𗞞𗨻𘂆𘋼𗤶𗅋𗯗𗪘𘟑𗤀𘓐𘟂 𘌽𘅣𗪘𘟑𗤀𘝞𘂤𘎪}} 

{{Tangut|𗷲𗿖𘒘𗓷𗼻𘍞𘓐𘟂𗒑𗉔𗼻𘍞𘛔𗅂𘴈 𘛫𘑲𘝦𘃡𗷲𗿖𗗙𘒘𗓷𗍁𗦳𘃡𗟻𘛫𗁡 𘒏𗀚𘞐𗼻𘍞𘙌𘃽𗵆𗣔𗈪𗋪𗿳𗋕𘛫𘑲 𗉮𘃛𗋚𗣈𘛫𗁡𘋩𗥦𗨳𘒘𗓷𗍁𗦳𘞪𗖌 𗅋𘄘𘛫𗁡𘒏𗩈𘑲𘋇𘙌𘒫𘒘𗓷𗍁𗹪𘓁 𗷲𗿖𗗙𘟤𘟤𗯹𗶷𗟻𘑲𘋇𗷲𗿖𗗙𗖖𘒣 𘒏𗩈𗣜𗫡𗆐𗧓𘀍𗅋𘄘𗅉𗔹𗑸𘉞𗫶𗫂 𘝶𗒘𘘣𗷲𗿖𘒣𗍳𘆄𘖑𗟭𗳒𗍁𗟨𘃡𗧓 𗫶𘌽𗍁𗅁𗫂𗥦𗰸𗅋𗃬𗩈𘟣𘖑𗫶𘄘𗩈 𗫂𗤋𘘣𘑲𘋇𗕣𗄈𗂈𗼛𘓐𘒫𗞞𗜍𗐱𘘣 𗷲𗿖𘒣𗥦𗰸𘃡𗧠𗌭𗉮𘃛𗞞𗰸𘉞𗅉𘕣 𗕣𘉞𘘣𘑲𘋇𗳱𗗙𗹡𗹐𘟂𗥤𗖵𘜤𗞞𘐉 𗅲𗳒𘙇𗀚𗦹𘃡𗴢𗁦𘟑𘚔𘞐𗪟𗤀𘓐𘟂 𘌽𘅣𘋅𘒘𘐆𘂤𘎪}}




