<!--Chapter 13 (如法受持分第十三)-->
{{Tangut|《𗹙𗖵𗒐𗧯𘊲𗰗𘕕𗡪》}}

{{Tangut|𗉘𘝨𗍏𘏞𘛛𗢳𗗙𘒣𘘣：「𗯨𗖻，𘌽𗖰𗚩𘕣𗦻？𗧓𘆄𘝶𗦜𗒐𗧯𗦇？」}}

{{Tangut|𗢳𗍏𘏞𘛛𗗙𘘣：「𘌽𗖰𗚩𗫂《𗵒𘗁𘄒𘎑𘏞𗓽𗕥》𗦻𗨻，𘌽𗦻𗏇𗖵𗍳𗒐𗧯𗦇。𘌽𗫂𘝶𗦜？𗍏𘏞𘛛，𗢳𘄒𘎑𘏞𗓽𗕥𗗙𘄒𘎑𘏞𗓽𗕥𗅔，𗌭𘄒𘎑𘏞𗓽𗕥𘟂𘘣。𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𘎪𗦇𗹙𗈪𘟣？」}}

{{Tangut|𗍏𘏞𘛛𗢳𗗙𘒣𘘣：「𗯨𗖻，𗌮𗆐𘎪𗦇𗤋𘃞。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𘕕𗡞𘜶𗡞𗯨𗐯𗅁𗽀𗎽𗄑𗄑，𗈪𗉘𗮅𘃞？」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗮅𘃞，𗯨𗖻。」}}

{{Tangut|「𗍏𘏞𘛛，𗌮𗆐𗱕𗽀𗎽𗗙𗽀𗎽𗅔，𗌭𗽀𗎽𗦻𗨻𘘣。𗌮𗆐𗯨𗐯𗗙𗯨𗐯𗅔，𗌭𗯨𗐯𗦻𗨻𘘣。𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𘕕𗰗𗍫𘍦𗳒𗌮𗆐𗈪𘟀？」}}

{{Tangut|「𗅋𘃞，𗯨𗖻。𘕕𗰗𗍫𘍦𗳒𗌮𗆐𘟀𘏚𗤋。𘝶𗦜𘃞？𗌮𗆐𘕕𗰗𗍫𘍦𗗙𘍦𗅔，𗌭𘕕𗰗𗍫𘍦𗦻𗨻𘘣。」}}

{{Tangut|「𗍏𘏞𘛛，𗓱𗩴𗾖𘈷、𗩴𗡸𘓐，𗣋𘀺𘔏𘜔𗍊𘛽𗤷𗅖𘈈，𗓱𗅉𘓐𘟣，𘌽𗖰𗚩𘂤𘙇𗫡𗥃𗣃𗖍𘆄𗒐𗧯，𘉑𗗙𘎪𘃡，𗌭𗋕𗼕𗩾𗮅。」}}

