<!--Chapter 18 (一體同觀分第十八)-->
{{Tangut|《𘓷𘞬𗯮𘝯𘊲𗰗𘉋𗡪》}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𗗙𗁮𗑉𗈪𘟣？」}}

{{Tangut|「𘟂𘃞，𗯨𗖻。𗌮𗆐𗁮𗑉𘟣。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𗗙𗹦𗑉𗈪𘟣？」}}

{{Tangut|「𘟂𘃞，𗯨𗖻。𗌮𗆐𗹦𗑉𘟣。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𗗙𘟛𗑉𗈪𘟣？」}}

{{Tangut|「𘟂𘃞，𗯨𗖻。𗌮𗆐𘟛𗑉𘟣。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𗗙𗹙𗑉𗈪𘟣？」}}

{{Tangut|「𘟂𘃞，𗯨𗖻。𗌮𗆐𗹙𗑉𘟣。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𗗙𗢳𗑉𗈪𘟣？」}}

{{Tangut|「𘟂𘃞，𗯨𗖻。𗌮𗆐𗢳𗑉𘟣。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗣋𘀺𗲌𗋽𘂤𘔏𗄑𗄑，𗢳𗋕𘔏𗈪𘎪？」}}

{{Tangut|「𘟂𘃞，𗯨𗖻？𗌮𗆐𗋕𘔏𘎪。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𘈩𗣋𘀺𗲌𗋽𘂤𘔏𗄑𗄑𗍊，𘌽𗍊𘆄𗣋𘀺𗲌𗋽𘟣，𗋕𗱕𗣋𘀺𗲌𗋽𗅁𘔏𗄑𗄑𗍊，𗢳𗯨𗐯𗫂，𗈪𗉘𗮅𘃞？」}}

{{Tangut|「𗮅𘃞，𗯨𗖻。」}}

{{Tangut|𗢳𗍏𘏞𘛛𗗙𘘣：「𗉘𗰣𗂧𘍞𗅁，𘋢𗋐𗄑𗄑𗗙𗉘𗰣𘋠𗤶，𗌮𗆐𗄊𗄻。𘝶𗦜𘃞？𗌮𗆐𗱕𗤶𗗙𗄊𗤶𗅔，𗌭𗤶𗦻𗨻𘘣。𘌽𗫂𘝶𗦜？𗍏𘏞𘛛，𗋚𗦎𗤶𘜘𘏚𗤋，𗌮𗫻𗤶𘜘𘏚𗤋，𗷝𗆐𗤶𘂆𘜘𘏚𗤋。」}}

