<!--Chapter 30 (一合理相分第三十)-->
{{Tangut|《𘈩𘜼𘍦𗧘𘊲𘕕𗰗𗡪》}}

{{Tangut|「𗍏𘏞𘛛，𗓱𗩴𗾖𘈷、𗩴𗡸𘓐，𘕕𗡞𘜶𗡞𗯨𗐯𘎩𗽀𗎽𗍊𗨻，𗉣𘕿𘝶𗦜？𘌽𗽀𗎽𘜔𗈪𗉘𗮅𘃞？」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗮅𘃞，𗯨𗖻。𘝶𗦜𘃞？𗓱𘌽𗽀𗎽𘜔𘞌𘟣，𗌭𗢳𗋕𗽀𗎽𘜔𗅋𘎪。𘌽𗫂𘝶𗦜？𗢳𗽀𗎽𘜔𗗙𗽀𗎽𘜔𗅔，𗌭𗽀𗎽𘜔𗦻𗨻𘘣。𗯨𗖻，𗌮𗆐𘙇𘎪𘕕𗡞𘜶𗡞𗯨𗐯𗫂𗯨𗐯𗅔，𗌭𗯨𗐯𗦻𗨻。𘌽𗫂𘝶𗦜？𗓱𗯨𗐯𘞌𘟣，𗌭𘈩𘜼𘍦𘟂。𗌮𗆐𘈩𘜼𘍦𗗙𘈩𘜼𘍦𗅔，𗌭𘈩𘜼𘍦𗦻𗨻𘘣。𗍏𘏞𘛛，𘈩𘜼𘍦𗫂𘎪𘏚𗤋𘟂。𗧀𗚉𗪙𘓐𗋕𘅣𗅴𗂆。」}}

[[Category:𗼇𗟲]]
[[Category:Buddhist texts in Tangut]]

𘚜𗼃𗰜𗡙𗨮.content:
{{header
 | title    ={{Tangut|𘚜𗼃𗰜𗡙𗨮}} (''Hymn of the Holy Origin of Tanguts'')
 | author   = 
 | section  =
 | previous = 
 | next     =
 | notes    =  
}}

{{Tangut|𘚜𗼃𗰜𗡙𗨮}}

<poem>
{{Tangut|𗥦𗰞𗱸𗍁𗛹𗋽𗎘, 𘅞𘔚𗔀𗹸𗲌𗴂𗹭, 𗼎𗾧𘕿𗗙𗂧𗋕𗁁.}}
{{Tangut|𘈑𗧁𗹭𗰗𗁞𘓐, 𘆽𘛽𘄽𗏁𘄷𘁿, 𗤳𗑝𗶚𗈪𘀟𘈷.}}
{{Tangut|𗲞𗺞𗴟𗐎𘝵𗕱𗅋𗿒𗯸𗰣𗼃, 𗉘𘝨𗂥𗣫𘃡𘖑𗳢𗿒𗤶𗧏.}}
{{Tangut|𘓫𗕪𗡮𗡮𗪯𗦉, 𗒹𘄄𗹠𗹠𗑟𘎆.}}
{{Tangut|𗂰𗱀𘐀𗗙𗉭𗀔𗕼, 𘐀𗗙𗉭𗕼𘋅𗨦𗣒, 𘂾𗱀𘂜𗑠𗣏𗸓𗶹, 𘂜𗑠𗣏𗸓𗶃𗃟𘑴.}}
{{Tangut|𗼨𗊠𘆝𘜂𗲋𗋽𘙌𗰛𗟟𗅋𗲁, 𗰂𗊡𗔀𗘍𗃦𘂹𗍁𗅁𗽒𗋚𗄿.}}
{{Tangut|𗬢𗤂𘁄𗰞𗳽𗥦𗅡, 𗞔𘇇𘙌𗸓𘇇𗅷𗯢, 𗱲𗱲𗘂𘗙𗽲𗢸𘘄, 𗱈𗑠𗈪𗔼𗱈𘁯𘖔.}}
{{Tangut|𘂜𗹦𗼓, 𗾞𗾞𘐘𗎰𘐘𗞞𗷼, 𘈚𘈚𘅟𘐏𘅟𗅋𗨂.}}
{{Tangut|𘉡𗣼𘖑𗳦𗆼𗞞𗈐, 𘃡𘃡𘖑𗼄, 𗲞𗺞𗋚𘅀𘝵𗸆𗇊.}}
{{Tangut|𘕜𗣊𗗙𗥼𘊸𗴺𘖖𗿾𗵛𘏚, 𘊟𗏎𗵒𗨔, 𗹠𘞗𗅋𗍣𗦻𗼨𗆟.}}
{{Tangut|𘁂𘝙𗵑, 𗋕𗰓𗄻, 𗱆𘕤𗈱𗀄𗀔𗱢𗧊, 𗋕𗗙𗅉𗏣𘓱𗦈𘈷𗵃𗑠𗋚𗰰𘕣𗦫𘔼? 𗏡𗏡𘈷𘃾𘚔𘚔𗈪𘃸.}}
{{Tangut|𗼇𗡱𗰂, 𗋚𘔴𗂥𘝨𗍫𘘄𘂬, 𗞞𘞵𗏡𗰗𘋠𘀄𘓄𗄊𗦳𗄭.}}
{{Tangut|𗒹𘆦𗳳𗀚𘋨𘃡𗆐, 𗼻𗁜𗼎𗾧𗈪𘗒𗄼𗅉𘓂𘙌𘟂?}}
{{Tangut|𘚶𗅡𗼃𘟙𗼈𗔁𘒏, 𘆝𗚚𘕿𘂬𘍳𘔝𗋕𗀔𗂧𗋚𘘓, 𘕜𗣊𘌽𘏰𘈑𗶟𘆝, 𗥷𗰜𗂰𘑪𘕿𗹠𘞗𗄼, 𗸆𘑉𗃏𗪲𗅨𗳉𘂴𘂤𗹡𗤶𗋐.}}
{{Tangut|𗥃𗏣𘄞𗴮𘅝𗖊𘐉, 𘈩𘇂𗼃𘋩𗑣𘒣𗀓.}}
{{Tangut|𗆖𗰩𗖚, 𘌇𗅋𗂍, 𗻨𘑪𗦬𘝚𘖑𗹬, 𗾔𘘂𗼑𘘂, 𗔼𗉜𗈪𗍣𗞞𗫉𗐱.}}
</poem>

[[Category:𗼇𗟲]]

𗼑𗼑𗫉𗊱.content:
{{header
 | title    ={{Tangut|𗼑𗼑𗫉𗊱}} (''Ode on Monthly Pleasures'')
 | author   = 
 | section  =
